	@Test
	void canonicalSnapshotPreservesLiteralFormsAndNestedTripleTerms() throws Exception {
		Literal plain = VALUE_FACTORY.createLiteral("plain");
		Literal languageRtl = VALUE_FACTORY.createLiteral("שלום", "he", Literal.BaseDirection.RTL);
		Literal languageLtr = VALUE_FACTORY.createLiteral("hello", "en", Literal.BaseDirection.LTR);
		Literal languageNone = VALUE_FACTORY.createLiteral("bonjour", "fr", Literal.BaseDirection.NONE);
		Literal typed = VALUE_FACTORY.createLiteral("0042", XSD.INTEGER);
		Value inner = VALUE_FACTORY.createTripleTerm(VALUE_FACTORY.createBNode("inner-subject"),
				VALUE_FACTORY.createIRI("urn:inner-predicate"), typed);
		Value nested = VALUE_FACTORY.createTripleTerm(VALUE_FACTORY.createBNode("outer-subject"),
				VALUE_FACTORY.createIRI("urn:outer-predicate"), inner);
		try (BindingSetReplayBuffer buffer = new BindingSetReplayBuffer(64)) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("b", VALUE_FACTORY.createBNode("stable-id"));
			row.addBinding("plain", plain);
			row.addBinding("languageRtl", languageRtl);
			row.addBinding("languageLtr", languageLtr);
			row.addBinding("languageNone", languageNone);
			row.addBinding("typed", typed);
			row.addBinding("triple", nested);
			buffer.append(row);
			buffer.seal();

			try (CloseableIteration<BindingSet> cursor = buffer.openCursor()) {
				BindingSet restored = cursor.next();
				assertEquals("stable-id", ((BNode) restored.getValue("b")).getID());
				assertEquals(plain, restored.getValue("plain"));
				assertEquals("שלום", ((Literal) restored.getValue("languageRtl")).getLabel());
				assertEquals("he", ((Literal) restored.getValue("languageRtl")).getLanguage().orElseThrow());
				assertEquals(Literal.BaseDirection.RTL,
						((Literal) restored.getValue("languageRtl")).getBaseDirection());
				assertEquals("hello", ((Literal) restored.getValue("languageLtr")).getLabel());
				assertEquals("en", ((Literal) restored.getValue("languageLtr")).getLanguage().orElseThrow());
				assertEquals(Literal.BaseDirection.LTR,
						((Literal) restored.getValue("languageLtr")).getBaseDirection());
				assertEquals("bonjour", ((Literal) restored.getValue("languageNone")).getLabel());
				assertEquals("fr", ((Literal) restored.getValue("languageNone")).getLanguage().orElseThrow());
				assertEquals(Literal.BaseDirection.NONE,
						((Literal) restored.getValue("languageNone")).getBaseDirection());
				assertEquals("0042", ((Literal) restored.getValue("typed")).getLabel());
				assertEquals(XSD.INTEGER, ((Literal) restored.getValue("typed")).getDatatype());
				assertEquals(nested, restored.getValue("triple"));
				assertFalse(cursor.hasNext());
			}
		}
	}

