	@Test
	void closeBetweenHasNextAndNextRaisesNoSuchElementInsteadOfReturningNull() throws Exception {
		try (BindingSetReplayBuffer buffer = new BindingSetReplayBuffer()) {
			buffer.append(row("x", VALUE_FACTORY.createLiteral("one")));
			buffer.seal();

			try (CloseableIteration<BindingSet> cursor = buffer.openCursor()) {
				assertTrue(cursor.hasNext());
				AtomicReference<BindingSet> result = new AtomicReference<>();
				AtomicReference<Throwable> failure = new AtomicReference<>();
				Thread worker = new Thread(() -> {
					try {
						result.set(cursor.next());
					} catch (Throwable t) {
						failure.set(t);
					}
				}, "replay-cursor-next");
				worker.setDaemon(true);
				try {
					synchronized (cursor) {
						worker.start();
						long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
						while (worker.isAlive() && worker.getState() != Thread.State.BLOCKED
								&& System.nanoTime() < deadline) {
							Thread.onSpinWait();
						}
						assertEquals(Thread.State.BLOCKED, worker.getState(),
								"worker must wait for the cursor monitor after hasNext()");
						cursor.close();
					}
				} finally {
					if (worker.isAlive()) {
						worker.interrupt();
					}
					worker.join(TimeUnit.SECONDS.toMillis(5));
					assertFalse(worker.isAlive(), "cursor worker must terminate after close");
				}
				assertNull(result.get(), "close must discard the prefetched value");
				assertTrue(failure.get() instanceof NoSuchElementException,
						"next must not return null after close wins the race");
			}
		}
	}

