	@Test
	void prefixSnapshotsHaveFixedBoundsAndOpaqueContinuationHandle() throws Exception {
		try (BindingSetReplayBuffer buffer = new BindingSetReplayBuffer()) {
			try (BindingSetReplayBuffer.PrefixCursor empty = buffer.openPrefixCursor(0L)) {
				assertEquals(0L, empty.endHandle());
				assertFalse(empty.hasNext());
			}

			buffer.append(row("x", VALUE_FACTORY.createLiteral("one")));
			buffer.append(row("x", VALUE_FACTORY.createLiteral("two")));
			BindingSetReplayBuffer.PrefixCursor first = buffer.openPrefixCursor(0L);
			BindingSetReplayBuffer.PrefixCursor second = buffer.openPrefixCursor(0L);
			long firstEnd = first.endHandle();
			assertTrue(firstEnd > 0L);
			assertEquals(firstEnd, second.endHandle(),
					"same append boundary should yield the same continuation handle");

			buffer.append(row("x", VALUE_FACTORY.createLiteral("three")));
			assertEquals("one", first.next().getValue("x").stringValue());
			assertEquals("two", first.next().getValue("x").stringValue());
			assertFalse(first.hasNext(), "a prefix cursor must not observe rows appended after its snapshot");
			assertEquals("one", second.next().getValue("x").stringValue());
			assertEquals("two", second.next().getValue("x").stringValue());
			assertFalse(second.hasNext(), "independent prefix cursors must share the same fixed bound");
			first.close();
			second.close();

			try (BindingSetReplayBuffer.PrefixCursor continuation = buffer.openPrefixCursor(firstEnd)) {
				assertTrue(continuation.endHandle() > firstEnd);
				assertEquals("three", continuation.next().getValue("x").stringValue());
				assertFalse(continuation.hasNext());
			}
		}
	}

