	private static void assertIndexedWildcardRowsKeepGlobalReplayOrderAndDuplicates(long indexBudget,
			boolean expectedSpill, Path directory) throws Exception {
		try (BindingSetReplayBuffer buffer = new BindingSetReplayBuffer(4096, directory);
				BindingSetReplayIndex index = new BindingSetReplayIndex(new String[] { "key" }, indexBudget,
						directory)) {
			MapBindingSet first = row("key", VALUE_FACTORY.createLiteral("one"));
			MapBindingSet wildcard = new MapBindingSet();
			MapBindingSet duplicate = row("key", VALUE_FACTORY.createLiteral("one"));
			long firstHandle = buffer.appendAndGetHandle(first);
			long wildcardHandle = buffer.appendAndGetHandle(wildcard);
			long duplicateHandle = buffer.appendAndGetHandle(duplicate);
			index.append(firstHandle, first);
			index.append(wildcardHandle, wildcard);
			index.append(duplicateHandle, duplicate);
			buffer.seal();
			index.seal();
			assertEquals(expectedSpill, hasFile(directory), "index budget should select the requested storage mode");

			try (CloseableIteration<Long> handles = index
					.openCandidateHandles(row("key", VALUE_FACTORY.createLiteral("one")))) {
				assertEquals(firstHandle, handles.next());
				assertEquals(wildcardHandle, handles.next());
				assertEquals(duplicateHandle, handles.next());
				assertFalse(handles.hasNext());
			}
		}
	}

	@Test
	void indexedBucketsHandleSignedHashesAndFilterCollisionsBeforeWildcard(@TempDir Path directory) throws Exception {
		IndexCandidatePair candidates = findSignedBucketCollision();
		try (BindingSetReplayIndex index = new BindingSetReplayIndex(new String[] { "key" }, 70_000, directory)) {
			MapBindingSet wildcard = new MapBindingSet();
			index.append(10L, candidates.first.row);
			index.append(20L, candidates.second.row);
			index.append(30L, wildcard);
			index.seal();

			try (CloseableIteration<Long> handles = index.openCandidateHandles(candidates.first.row)) {
				assertTrue(handles.hasNext());
				assertEquals(10L, handles.next(), "the exact-hash row must be retained");
				assertEquals(30L, handles.next(), "wildcard rows must merge after exact candidates");
				assertFalse(handles.hasNext(), "a distinct hash in the same bucket must be filtered out");
			}
		}
	}

	private static IndexCandidatePair findSignedBucketCollision() {
		final int bucketCount = 4096;
		Map<Integer, IndexCandidate> firstByBucket = new HashMap<>();
		for (int i = 0; i < 100_000; i++) {
			Value value = VALUE_FACTORY.createLiteral("index-candidate-" + i);
			MapBindingSet row = row("key", value);
			long hash = replayIndexHash(value);
			int bucket = replayIndexBucket(hash, bucketCount);
			IndexCandidate previous = firstByBucket.putIfAbsent(bucket, new IndexCandidate(row, hash));
			if (previous != null && previous.hash != hash
					&& (hasSignedIntCast(previous.hash) || hasSignedIntCast(hash))) {
				return new IndexCandidatePair(previous, new IndexCandidate(row, hash));
			}
		}
		throw new AssertionError("could not find a deterministic signed-hash bucket collision");
	}

	private static long replayIndexHash(Value value) {
		long hash = 0xcbf29ce484222325L;
		hash ^= value.hashCode();
		return hash * 0x100000001b3L;
	}

	private static int replayIndexBucket(long hash, int bucketCount) {
		long mixed = (hash ^ (hash >>> 32)) & Long.MAX_VALUE;
		return (int) (mixed % bucketCount);
	}

	private static boolean hasSignedIntCast(long hash) {
		long mixed = (hash ^ (hash >>> 32)) & Long.MAX_VALUE;
		return (int) mixed < 0;
	}

	private static final class IndexCandidate {
		private final MapBindingSet row;
		private final long hash;

		private IndexCandidate(MapBindingSet row, long hash) {
			this.row = row;
			this.hash = hash;
		}
	}

	private static final class IndexCandidatePair {
		private final IndexCandidate first;
		private final IndexCandidate second;

		private IndexCandidatePair(IndexCandidate first, IndexCandidate second) {
			this.first = first;
			this.second = second;
		}
	}

	private static MapBindingSet row(String name, Value value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, value);
		return row;
	}

	private static boolean hasFile(Path directory) throws Exception {
		try (Stream<Path> files = Files.list(directory)) {
			return files.findAny().isPresent();
		}
	}

	private static final class NullPlaceholderBindingSet extends AbstractBindingSet {
		private final String name;

		private NullPlaceholderBindingSet(String name) {
			this.name = name;
		}

		@Override
		public Set<String> getBindingNames() {
			return Set.of(name);
		}

		@Override
		public Value getValue(String bindingName) {
			return null;
		}

		@Override
		public Binding getBinding(String bindingName) {
			return null;
		}

		@Override
		public boolean hasBinding(String bindingName) {
			return name.equals(bindingName);
		}

		@Override
		public int size() {
			return 1;
		}

		@Override
		public java.util.Iterator<Binding> iterator() {
			return java.util.Collections.emptyIterator();
		}
	}
